import subprocess,json
refs=['origin/main','origin/opencode-checkpoints/7','origin/opencode-checkpoints/11','origin/opencode-checkpoints/14','origin/opencode-checkpoints/15','origin/opencode-checkpoints/18','origin/opencode-deployments/11','origin/opencode-deployments/15','origin/opencode-deployments/18','origin/opencode/42187724047']
for ref in refs:
    print('\n###',ref)
    for f in ('index.html','game.js','styles.css'):
        p=subprocess.run(['git','show',f'{ref}:{f}'],capture_output=True,text=True)
        if p.returncode==0:
            text=p.stdout
            import re
            title=re.search(r'<title>(.*?)</title>',text,re.I|re.S)
            print(f, 'bytes',len(text.encode()), 'title',title.group(1).strip() if title else '')
    p=subprocess.run(['git','show',f'{ref}:.omgithub/conversation.json'],capture_output=True,text=True)
    if p.returncode==0:
        try:
            data=json.loads(p.stdout)
            msgs=data.get('messages',[])
            users=[m.get('text','') for m in msgs if m.get('type')=='user']
            print('user messages:',len(users))
            for m in users[-3:]: print(' ',re.sub(r'\s+',' ',m)[:280])
        except Exception as e: print('json err',e)
