const wait = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
  const page = targets.find(t => t.type === 'page' && t.url.startsWith('http://127.0.0.1:8765/'));
  if (!page) throw new Error('Reinos Chromium page not found');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let seq = 0;
  const pending = new Map(), errors = [];
  ws.onmessage = e => {
    const m = JSON.parse(e.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
    if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.text);
    if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') errors.push(m.params.args.map(a => a.value || a.description).join(' '));
  };
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  const call = (method, params={}) => new Promise((resolve, reject) => {
    const id = ++seq; pending.set(id, m => m.error ? reject(new Error(m.error.message)) : resolve(m)); ws.send(JSON.stringify({id, method, params}));
  });
  const evalJS = async expression => {
    const r = await call('Runtime.evaluate', {expression, awaitPromise:true, returnByValue:true});
    if (r.result?.exceptionDetails) throw new Error(r.result.exceptionDetails.text);
    return r.result?.result?.value;
  };
  await call('Runtime.enable'); await call('Log.enable'); await call('Page.enable');
  const initial = await evalJS(`({roster:document.querySelectorAll('[data-fighter]').length,cls:document.querySelector('#classSelect').value,paused:document.querySelector('#menuBtn')?.getAttribute('aria-pressed'),rect:(()=>{const r=document.querySelector('#game').getBoundingClientRect();return {left:r.left,top:r.top,width:r.width,height:r.height}})()})`);
  await evalJS(`document.querySelector('#restartBtn').click()`);
  await wait(100);
  // Reproduce the game's initial open-tile search to find a free, adjacent placement tile.
  const plan = await evalJS(`(async()=>{const map=await (await fetch('assets/ao/map.json')).json();const open=(x,y)=>x>=0&&y>=0&&x<map.width&&y<map.height&&!map.tiles[y][x].b;const p=[[43,46],[44,43],[43,49],[46,46],[57,46],[56,43],[57,49],[54,46]];const home=p.map(([x,y])=>[x,y]);for(let i=0;i<p.length;i++){let found=null;for(let radius=0;radius<10&&!found;radius++)for(let dy=-radius;dy<=radius&&!found;dy++)for(let dx=-radius;dx<=radius&&!found;dx++){const x=p[i][0]+dx,y=p[i][1]+dy;if(open(x,y)&&!home.some((q,j)=>j!==i&&q[0]===x&&q[1]===y))found=[x,y]}if(found)home[i]=found;}const [px,py]=home[0];let candidate=null;for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1],[2,0],[-2,0],[0,2],[0,-2]]){const x=px+dx,y=py+dy;if(open(x,y)&&!home.some(q=>q[0]===x&&q[1]===y)){candidate=[x,y];break}}const c=document.querySelector('#game'),r=c.getBoundingClientRect(),tile=Math.max(24,Math.min(40,r.width/25,r.height/16));return {home,player:[px,py],candidate,rect:{left:r.left,top:r.top,width:r.width,height:r.height},tile,point:candidate&&{x:r.left+r.width/2+(candidate[0]-px)*tile,y:r.top+r.height/2+(candidate[1]-py)*tile}}})()`);
  let placement = {plan, before:null, after:null};
  if (plan.candidate) {
    await evalJS(`(()=>{const s=document.querySelector('#npcPicker');s.value='chaoticPaladin';s.dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('#npcPlaceToggle').click()})()`);
    placement.before = await evalJS(`({active:document.querySelector('#npcPlaceToggle').getAttribute('aria-pressed'),toast:document.querySelector('#toast').textContent})`);
    await call('Input.dispatchMouseEvent',{type:'mouseMoved',x:plan.point.x,y:plan.point.y});
    await call('Input.dispatchMouseEvent',{type:'mousePressed',x:plan.point.x,y:plan.point.y,button:'left',clickCount:1});
    await call('Input.dispatchMouseEvent',{type:'mouseReleased',x:plan.point.x,y:plan.point.y,button:'left',clickCount:1});
    placement.after = await evalJS(`({active:document.querySelector('#npcPlaceToggle').getAttribute('aria-pressed'),toast:document.querySelector('#toast').textContent,target:document.querySelector('#targetName').textContent})`);
  }
  await wait(900);
  const meleeBefore = await evalJS(`({target:document.querySelector('#targetName').textContent,status:document.querySelector('#targetStatus').textContent,disabled:document.querySelector('#attackBtn').disabled,feed:document.querySelector('#killFeed').innerText})`);
  await evalJS(`document.dispatchEvent(new KeyboardEvent('keydown',{key:'f',bubbles:true}))`);
  const meleeAfter = await evalJS(`({toast:document.querySelector('#toast').textContent,log:document.querySelector('#battleLog').innerText,feed:document.querySelector('#killFeed').innerText})`);
  // Switch to mage, select a ranged damage spell, and target the placed NPC on its placement tile.
  await evalJS(`(()=>{const s=document.querySelector('#classSelect');s.value='mage';s.dispatchEvent(new Event('change',{bubbles:true}));document.querySelector('#spellSlots .spell-slot[data-skill="2"]').click()})()`);
  const aim = await evalJS(`({hint:document.querySelector('#spellHint').textContent,pressed:document.querySelector('#spellSlots .spell-slot[data-skill="2"]').getAttribute('aria-pressed'),cursor:getComputedStyle(document.querySelector('#game')).cursor})`);
  const p = plan.point;
  await call('Input.dispatchMouseEvent',{type:'mouseMoved',x:p.x,y:p.y});
  await call('Input.dispatchMouseEvent',{type:'mousePressed',x:p.x,y:p.y,button:'left',clickCount:1});
  await call('Input.dispatchMouseEvent',{type:'mouseReleased',x:p.x,y:p.y,button:'left',clickCount:1});
  const spell = await evalJS(`({toast:document.querySelector('#toast').textContent,hp:document.querySelector('#targetStatus').textContent,log:document.querySelector('#battleLog').innerText,feed:document.querySelector('#killFeed').innerText,selected:document.querySelector('#spellSlots .spell-slot[data-skill="2"]')?.getAttribute('aria-pressed')})`);
  const shot = await call('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});
  require('fs').writeFileSync('/tmp/opencode/reinos-combat.png',Buffer.from(shot.result.data,'base64'));
  await wait(500);
  const end = await evalJS(`({toast:document.querySelector('#toast').textContent,counts:[document.querySelector('#healthPotionCount').textContent,document.querySelector('#manaPotionCount').textContent],hp:document.querySelector('#healthValue').textContent,skills:document.querySelectorAll('#spellSlots .spell-slot').length,roster:document.querySelectorAll('[data-fighter]').length})`);
  console.log(JSON.stringify({initial,plan,placement,meleeBefore,meleeAfter,aim,spell,end,errors},null,2));
  ws.close();
})().catch(e=>{console.error(e);process.exit(1)});

